arguments.command:
cat << 'EOF' > /tmp/stackalloc_nint.cs
Span<nint> span = stackalloc nint[4];
for (int i = 0; i < span.Length; i++)
    span[i] = (nint)(i * 10);

for (int i = 0; i < span.Length; i++)
    Console.WriteLine($"span[{i}] = {span[i]}");

Console.WriteLine($"nint size: {sizeof(nint)} bytes");
EOF
dotnet-script /tmp/stackalloc_nint.cs 2>&1 || dotnet script /tmp/stackalloc_nint.cs 2>&1 || {
  # Fall back to a full project
  mkdir -p /tmp/stackalloc_test && cd /tmp/stackalloc_test
  dotnet new console --force -o . -n StackAllocTest --no-restore -q 2>/dev/null
  cat << 'PROG' > Program.cs
unsafe
{
    Span<nint> span = stackalloc nint[4];
    for (int i = 0; i < span.Length; i++)
        span[i] = (nint)(i * 10);

    for (int i = 0; i < span.Length; i++)
        Console.WriteLine($"span[{i}] = {span[i]}");

    Console.WriteLine($"nint size: {sizeof(nint)} bytes");
}
